const input = require('fs').readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const code = input.charCodeAt(pos);
    if (code < 48 || code > 57) break;
    value = value * 10 + code - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();

const edgeU = new Int32Array(M);
const edgeV = new Int32Array(M);
const degree = new Int32Array(N);

for (let i = 0; i < M; i++) {
  const u = nextInt() - 1;
  const v = nextInt() - 1;
  edgeU[i] = u;
  edgeV[i] = v;
  degree[u]++;
  degree[v]++;
}

const offset = new Int32Array(N + 1);
for (let i = 0; i < N; i++) offset[i + 1] = offset[i] + degree[i];

const adjacency = new Int32Array(2 * M);
const cursor = new Int32Array(offset);
for (let i = 0; i < M; i++) {
  const u = edgeU[i];
  const v = edgeV[i];
  adjacency[cursor[u]++] = v;
  adjacency[cursor[v]++] = u;
}

const visited = new Uint8Array(N);
const marked = new Int32Array(N);
const queue = new Int32Array(N);
let componentToken = 0;

for (let start = 0; start < N; start++) {
  if (visited[start]) continue;

  let head = 0;
  let tail = 0;
  queue[tail++] = start;
  visited[start] = 1;

  while (head < tail) {
    const u = queue[head++];
    for (let i = offset[u]; i < offset[u + 1]; i++) {
      const v = adjacency[i];
      if (!visited[v]) {
        visited[v] = 1;
        queue[tail++] = v;
      }
    }
  }

  componentToken++;
  for (let i = 0; i < tail; i++) {
    const u = queue[i];
    if (degree[u] < tail - 1) {
      for (let j = offset[u]; j < offset[u + 1]; j++) {
        marked[adjacency[j]] = componentToken;
      }
      for (let j = 0; j < tail; j++) {
        const v = queue[j];
        if (v !== u && marked[v] !== componentToken) {
          process.stdout.write(`${u + 1} ${v + 1}\n`);
          process.exit(0);
        }
      }
    }
  }
}

process.stdout.write('-1\n');
